 messageEditor.element.addEventListener('keydown',event=>{if(mentionList.hidden)return;const items=[...mentionList.children],current=items.findIndex(item=>item.classList.contains('is-active'));if(event.key==='ArrowDown'||event.key==='ArrowUp'){event.preventDefault();event.stopImmediatePropagation();const next=(current+(event.key==='ArrowDown'?1:-1)+items.length)%items.length;items.forEach((item,index)=>item.classList.toggle('is-active',index===next));}else if(event.key==='Enter'||event.key==='Tab'){event.preventDefault();event.stopImmediatePropagation();items[Math.max(0,current)]?.click();}else if(event.key==='Escape'){event.stopImmediatePropagation();hideMentions();}},true);
 messageEditor.element.addEventListener('blur',()=>setTimeout(hideMentions,150));
 composeBanner.addEventListener('keydown',event=>{if(event.key==='Escape')clearCompose();});messageEditor.element.addEventListener('keydown',event=>{if(event.key==='Escape'&&(replyTarget||editTarget)&&mentionList.hidden){event.preventDefault();clearCompose();}});
 // Group chats can start a poll: the question becomes the message text.
 const pollStart=node('button','Poll','composer-poll');pollStart.type='button';pollStart.title='Start a poll';$('send-message').before(pollStart);
 pollStart.onclick=()=>{const dialog=makeDialog('Start a poll'),form=node('form'),question=node('input'),options=node('textarea'),multiple=node('input'),error=node('p','','communication-error'),actions=node('div',undefined,'communication-dialog-actions'),cancel=node('button','Cancel'),send=node('button','Send poll','communication-primary');question.required=true;question.maxLength=200;options.rows=4;options.placeholder='One option per line (2–10)';multiple.type='checkbox';const pick=node('label',undefined,'communication-required-choice');pick.append(multiple,node('span','Allow more than one answer'));cancel.type='button';cancel.onclick=()=>dialog.close();send.type='submit';actions.append(cancel,send);const reference=uid(),id=active;form.onsubmit=async event=>{event.preventDefault();const list=options.value.split('\n').map(value=>value.trim()).filter(Boolean);if(list.length<2||list.length>10){error.textContent='Add 2–10 options, one per line.';return;}send.disabled=true;try{const message=await api('threads/'+id+'/messages','POST',{body:question.value,poll:{question:question.value,options:list,multiple:multiple.checked},requestId:reference});dialog.close();if(id===active&&!messageIds.has(message.id)){messages.push(message);appendMessage(message);$('conversation-messages').scrollTop=$('conversation-messages').scrollHeight;}await loadThreads();}catch(err){error.textContent=err.message;send.disabled=false;}};form.append(label('Question',question),label('Options',options),pick,error,actions);dialog.append(form);dialog.showModal();question.focus();};
 messageEditor.element.addEventListener('keydown',event=>{if(event.key==='Enter'&&!event.shiftKey&&!event.isComposing&&((event.ctrlKey||event.metaKey)||!messageEditor.inList())){event.preventDefault();$('message-composer').requestSubmit();}});$('conversation-messages').addEventListener('scroll',()=>markConversation());window.addEventListener('hashchange',view);window.addEventListener('required-reading-changed',event=>{if(!event.detail.blocked&&session){view();loadThreads();}});window.addEventListener('focus',()=>{if(session&&!appRequiredReading.blocked){view();if(active)loadMessages();}});
